{
  "window_id": "w0026",
  "observed_failures": [
    {
      "id": "F1_empty_string_instead_of_null",
      "detail": "Row 078.jpg has total_amount = \"\" (empty string) in the delivered xlsx. Task required real null for failed extraction; empty string is a distinct cell value and fails line-by-line grading.",
      "evidence": "predictions row 078.jpg: total_amount == \"\"; feedback.field_feedback marks amount_correct=false for 078.jpg"
    },
    {
      "id": "F2_ocr_digit_confusion_survives_voting",
      "detail": "074.jpg total predicted \"702.00\" though receipt clearly shows 102.00 three times (Subtotal, Total incl. of GST, Total Amt Rounded, Payment). Multi-variant voting picked the majority tier match from the (noisy) 'Total Amt Rounded' line and did not cross-validate against repeated identical candidates on Subtotal / Payment.",
      "evidence": "image 074.jpg shows Total Excl./Incl./Rounded/Payment all = 102.00; prediction = \"702.00\"; agent traced voting to tier-3 tie 702 (2 variants) vs 102 (1 variant)."
    },
    {
      "id": "F3_rounding_adjustment_not_honored",
      "detail": "077.jpg shows 'Total (Inclusive of GST): 23.26' then 'Rounding Adj: -0.01' then 'TOTAL: 23.25'. Agent returned 23.26 instead of the rounded final 23.25. Tier logic picked the first/highest-priority 'TOTAL'-keyword match seen, not the final post-rounding TOTAL line.",
      "evidence": "image 077.jpg final line 'TOTAL: 23.25'; prediction 23.26."
    },
    {
      "id": "F4_date_format_ambiguity_on_034",
      "detail": "034.jpg date predicted 2018-08-09; receipt displays 'Date: 09/03/2018' (DD/MM/YYYY, Malaysian convention). Either OCR confused 03↔08 or the parser is sensitive to variant OCR reads without cross-variant date voting that weights locale convention.",
      "evidence": "image 034.jpg Date 09/03/2018; prediction 2018-08-09."
    },
    {
      "id": "F5_cash_received_not_excluded_initially",
      "detail": "078.jpg 'Grand Total 92.80' was dropped and 'Cash Received 100.00' was almost picked by two-line fallback because exclusion list only had 'CASH TENDERED', not 'CASH RECEIVED' / 'CASH PAYMENT'. The agent patched this mid-run but the final write still ended with empty string, suggesting the fallback path also failed and the null-safe writer emitted \"\" not None.",
      "evidence": "trajectory shows str_replace broadening regex to r'\\bCASH\\s+(TENDERED|RECEIVED|PAYMENT)\\b'; predictions still have 078.jpg amount == \"\"."
    },
    {
      "id": "F6_termination_at_iteration_cap",
      "detail": "Source agent hit max_iterations (65) without natural completion. Repair loop converged to within 1-2 remaining images but ran out of turns, so last-minute fixes (exclusion tweak, voting refactor) were never validated end-to-end and the final xlsx still carried a pre-fix artifact (empty string for 078).",
      "evidence": "execution_metadata.termination_reason = 'max_iterations'; acp_stop_reason = 'max_turn_requests'."
    }
  ],
  "root_causes": [
    {
      "id": "RC1",
      "summary": "Output serialization in the current xlsx guidance does not force None for failed-extraction cells. Even the draft xlsx SKILL mentions it but the original run clearly produced \"\"; pandas default for missing strings in an object column becomes NaN or \"\" depending on build path, and there is no explicit sanitization step before to_excel()."
    },
    {
      "id": "RC2",
      "summary": "Total-extraction logic in image-ocr SKILL is keyword-first but not 'final-total-line last'. Receipts frequently repeat TOTAL (pre-tax / incl-GST / post-rounding). The priority tiers resolve the keyword but not the temporal 'last authoritative TOTAL after rounding' rule, which is what graders encode."
    },
    {
      "id": "RC3",
      "summary": "Multi-variant OCR voting is per-tier majority on extracted values only; it does not use repeated-number consensus from the full OCR text. On digit confusions like 1↔7, the correct value is often present multiple times elsewhere (Subtotal, Payment, Total Rounded) and that structural redundancy is thrown away."
    },
    {
      "id": "RC4",
      "summary": "Exclusion list under-specified: covers 'CASH TENDERED' but not other cash-side labels ('CASH RECEIVED', 'CASH PAYMENT', 'CASH', 'VISA', 'MASTERCARD', 'CARD', 'PAID', 'TENDER'). Two-line fallback then latches onto payment-method lines whose amounts are often >= total."
    },
    {
      "id": "RC5",
      "summary": "Date extraction lacks locale/convention bias. For Malaysian receipts (the obvious domain of these samples: RM, GST, SST), DD/MM/YYYY should outrank MM/DD/YYYY when both parse. There is also no cross-variant voting on the date; a single OCR mis-read on one variant can change the winner."
    },
    {
      "id": "RC6",
      "summary": "No 'budget-aware' plan: the method rewrites and re-runs the whole batch on every tweak instead of caching per-image OCR text and only re-running the field extractor, so iteration budget is burned on re-OCR rather than on logic fixes."
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defects": [
        "Priority tiers do not specify 'prefer the LAST matching line within the highest priority tier', which is the empirical rule for post-rounding final totals.",
        "Two-line fallback is unguarded: it fires whenever the keyword line has no digits, even if the next line is a payment-method/card/cash line.",
        "Exclusion list missing CASH RECEIVED, CASH PAYMENT, CASH, VISA, MASTERCARD, CARD, PAID, TENDER, ROUNDING, ROUNDING ADJ (the adjustment amount itself is not the total).",
        "No cross-variant consensus that leverages repetition of the same numeric value elsewhere in the text (Subtotal == Total == Payment is strong evidence against an outlier OCR read).",
        "Date extraction has no explicit 'prefer DD/MM/YYYY when ambiguous' toggle for Malaysian-style receipts, no voting across OCR variants, and no sanity check (year in a plausible range).",
        "No explicit statement that final output values must be returned as None (not '', not 'None', not NaN) when extraction fails."
      ]
    },
    {
      "skill": "xlsx",
      "defects": [
        "Strict-schema section mentions None vs '' but does not prescribe a mandatory sanitization pass (e.g., df.replace({'': None, 'nan': None, 'None': None}) and df.where(df.notna(), None)) immediately before to_excel().",
        "No prescribed post-write re-read-and-assert step that verifies empty cells are truly empty (not \"\") and that all amounts are strings matching r'^\\d+\\.\\d{2}$' or null.",
        "No guidance on sheet-name casing: the task fixes 'results' (lowercase). The checklist mentions it but should elevate to a required assertion before closing the writer."
      ]
    },
    {
      "skill": "openai-vision",
      "defects": [
        "No pattern for using vision as a low-cost rescue step for a small residual set (the N receipts where Tesseract produced ambiguous results). The source run never invoked vision even when stuck on ~2 images for many iterations."
      ]
    },
    {
      "skill": "pdf",
      "defects": [
        "Not materially implicated by this task; however, since receipts sometimes arrive as scanned PDFs, cross-reference to image-ocr's structured-field extraction is missing (a one-line pointer would make the batch pipeline reusable)."
      ]
    },
    {
      "skill": "video-frame-extraction",
      "defects": [
        "Not implicated by this task."
      ]
    }
  ],
  "repair_recommendations": [
    {
      "skill": "image-ocr",
      "change": "Add an explicit 'Receipt Total Selection Rules' subsection that codifies: (a) within the highest-priority tier that has any match, prefer the LAST matching line (bottom-of-receipt wins) over the first; (b) when the chosen line's extracted number differs from a number that appears >=2 times elsewhere in the OCR text (e.g., Subtotal, Payment, Total Rounded), prefer the repeated value — this neutralizes 1↔7, 0↔8, 3↔5 digit confusions."
    },
    {
      "skill": "image-ocr",
      "change": "Expand EXCLUSIONS to include: SUBTOTAL, SUB TOTAL, TAX, GST, SST, DISCOUNT, CHANGE, CASH, CASH TENDERED, CASH RECEIVED, CASH PAYMENT, VISA, MASTERCARD, MASTER CARD, CARD, DEBIT, CREDIT, PAID, TENDER, TENDERED, ROUNDING, ROUNDING ADJ, ADJUSTMENT. Match as word-boundary regex, case-insensitive. Apply exclusions to BOTH the keyword line and any two-line-fallback next line."
    },
    {
      "skill": "image-ocr",
      "change": "Guard the two-line fallback: only descend to the next line if the keyword line has no digits AND the next non-empty line passes exclusion AND the next line's value is not larger than the largest numeric already seen with a 'SUBTOTAL' or 'TOTAL' keyword (this blocks CASH 100.00 from capturing a 92.80 total)."
    },
    {
      "skill": "image-ocr",
      "change": "Add a structured date-selection subsection: (a) run DATE_PATTERNS on every OCR variant; (b) when both DD/MM/YYYY and MM/DD/YYYY parse the same token, prefer DD/MM/YYYY (receipts in this domain are consistently DD/MM); (c) vote across variants and pick the ISO date with the highest frequency, tiebreaking by earliest-in-reading-order; (d) reject years outside a configurable sanity range (default 2000–2099)."
    },
    {
      "skill": "image-ocr",
      "change": "State the output contract for structured extraction explicitly: on failure, return Python None for every field, never '', 'None', or NaN. Downstream callers MUST propagate None unchanged."
    },
    {
      "skill": "image-ocr",
      "change": "Document a caching recipe: run multi_pass_ocr once per image and persist the raw text (e.g., to a JSON sidecar keyed by filename+md5). Re-runs of the field extractor should read the cache instead of re-OCRing — this is what makes iterative repair feasible within turn budgets."
    },
    {
      "skill": "xlsx",
      "change": "Promote the strict-schema sanitization to a required pre-write step with explicit code: coerce the output DataFrame with df = df.astype(object).where(df.notna(), None); then df.replace({'': None, 'nan': None, 'NaN': None, 'None': None}, inplace=True); then to_excel(..., sheet_name=<exact name>, index=False). Make this the canonical pattern in the 'Strict-Schema Outputs' section."
    },
    {
      "skill": "xlsx",
      "change": "Require a post-write verification block that re-reads the file with openpyxl (not pandas, to see true cell type) and asserts: (a) exactly one sheet with the exact required name (case-sensitive); (b) header row equals the required columns in order; (c) for every numeric-looking string column, each non-null cell matches a regex (e.g., r'^\\d+(?:\\.\\d{2})?$' for amounts formatted to 2 decimals); (d) blank-missing cells are truly empty (cell.value is None), not the literal strings '' / 'None' / 'nan'."
    },
    {
      "skill": "xlsx",
      "change": "Add a short 'string-vs-float amount pitfall' callout: amounts specified as '47.70' must be written as Python str; using float will drop the trailing zero and change the cell type, failing graders."
    },
    {
      "skill": "openai-vision",
      "change": "Add a 'Residual-Rescue Pattern' subsection: when a batch OCR pipeline leaves <= K images with low confidence or unresolved key fields, invoke GPT-4o vision with detail='high' on just those images, with a tightly-scoped prompt asking for ONLY {date, total_amount} as JSON. This bounds cost while recovering the long tail. Include a token budget estimate and a reminder that vision output must also be sanitized to None on failure."
    },
    {
      "skill": "pdf",
      "change": "Add a single cross-reference line to image-ocr's structured-field extraction section, noting that scanned-receipt PDFs should be rasterized via pdf2image and then routed through the same per-image pipeline (not treated as native PDF text)."
    }
  ],
  "confidence": {
    "level": "medium-high",
    "rationale": "Field-level feedback precisely localizes four failing cells (078 amount, 074 amount, 077 amount, 034 date). Visual inspection of those receipts plus the trajectory of in-flight fixes (broadening exclusions, moving to candidate-list voting, two-line fallback misfires) makes the root causes unambiguous for F1, F2, F3, F5, F6. F4's exact failure mode (OCR 03→08 vs locale ambiguity) cannot be fully disambiguated without the OCR text per variant, so the recommendation covers both.",
    "caveats": "Recommendations are stated as skill-document changes only (image-ocr, xlsx, openai-vision, pdf, video-frame-extraction). No oracle answer values were read or inferred; all failure examples come from field_feedback booleans and visible receipt content."
  }
}
